import { defineSchema, lazySchema } from "../../../src/schemas/index.js";
import { createArgParser, parseArgsOrThrow } from "../../shared/args.js";
import { INVALID_ARGUMENT } from "../../../src/errors/index.js";
import { COMMAND_CATEGORIES } from "../../help/types.js";
import { generateCommandSchema, generateSchema } from "./command.js";
const getSchemaArgsSchema = defineSchema((v) => v.object({
    category: v.enum(COMMAND_CATEGORIES).optional(),
}));
const SchemaArgsSchema = lazySchema(getSchemaArgsSchema);
export const parseSchemaArgs = createArgParser(SchemaArgsSchema, {
    category: { keys: ["category", "c"], type: "string" },
}, { rejectUnknown: true });
export async function handleSchemaCommand(args) {
    const opts = parseArgsOrThrow(parseSchemaArgs, "schema", args);
    const commandName = args._[1];
    if (commandName) {
        const schema = generateCommandSchema(commandName);
        if (!schema) {
            throw INVALID_ARGUMENT.create({
                detail: `Unknown command: ${commandName}`,
                context: { command: "schema", requestedCommand: commandName },
            });
        }
        console.log(JSON.stringify(schema, null, 2));
        return;
    }
    const schema = generateSchema(opts.category);
    console.log(JSON.stringify(schema, null, 2));
}
